<script setup lang="ts">
import {ref,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {pages,type Page,statusType} from './catalog'
import {state,persist,downloadDemo} from './store'
const props=defineProps<{page:Page,persona:string}>();const emit=defineEmits(['navigate','export'])
const reviewFilter=ref('全部'),reviewQuery=ref(''),notePage=ref('dashboard'),reviewOpen=ref(false)
const reviewPages=computed(()=>pages.filter(p=>(reviewFilter.value==='全部'||p.phase.includes(reviewFilter.value))&&(p.title+p.req).includes(reviewQuery.value)))
const stateChoice=ref('未验证'),verification=ref(''),address=ref(''),authMode=ref('邮箱验证码'),verified=ref(false),sent=ref(false),consent=ref(false),files=ref<string[]>(['谢幕照片01.jpg','摄影授权声明.pdf'])
const externalUnavailable=computed(()=>['已到期','已撤销','次数用尽','IP不匹配'].includes(stateChoice.value))
const ocrPage=ref(12),selectedBlock=ref(0),lowOnly=ref(false),ocrMode=ref('人工校订稿'),blocks=ref([{text:'第二幕 · 月上柳梢',confidence:99},{text:'这条河，记得每一个归来的人。',confidence:96},{text:'灯光渐亮，远处传来渡船的声音。',confidence:72}]),ocrSaved=ref(false)
const position=ref(754),speed=ref('1.0×'),playing=ref(false),activeTab=ref('转写校订'),annotation=ref(''),clipStart=ref(754),clipEnd=ref(814),clipPurpose=ref(''),speaker=ref('说话人1'),region=ref<{x:number,y:number}|null>(null)
const segments=ref([{start:742,end:754,text:'这一段的情绪可以再慢一点。',speaker:'说话人1',confirmed:false},{start:754,end:769,text:'等灯光落下，再接下一句。',speaker:'说话人2',confirmed:true},{start:770,end:791,text:'观众需要一点时间理解人物的选择。',speaker:'说话人1',confirmed:false}])
const question=ref(''),answer=ref(''),answerState=ref(''),scope=ref('春江月 / 2026年 / 已确认资料'),messages=ref<string[]>([]),answerLoading=ref(false),sourceOpen=ref(false),feedback=ref('')
const selectedPhotos=ref<number[]>([1]),split=ref(false),photoReason=ref('表情自然，舞台主体完整'),compareZoom=ref(100)
const calendar=['日','一','二','三','四','五','六']
function remember(){persist();ElMessage.success('评审意见已保存到本浏览器')}
function review(id:string){notePage.value=id;reviewOpen.value=true}
function verify(){if(!address.value.trim()){ElMessage.warning('请填写接收身份');return}if(verification.value!=='246810'){ElMessage.error('验证未通过，请检查输入后重试。演示验证码为246810。');return}verified.value=true;stateChoice.value='已验证';ElMessage.success('已进入模拟验证后的页面')}
function saveOCR(){state.drafts['ocr-review']={page:ocrPage.value,blocks:blocks.value};persist();ocrSaved.value=true;ElMessage.success('校订演示稿已保存，原图保持不变')}
function splitBlock(){const b=blocks.value[selectedBlock.value];if(!b)return;const middle=Math.ceil(b.text.length/2);blocks.value.splice(selectedBlock.value,1,{...b,text:b.text.slice(0,middle)},{...b,text:b.text.slice(middle)});ocrSaved.value=false}
function mergeBlock(){const i=selectedBlock.value;if(!blocks.value[i+1]){ElMessage.info('请选择有下一块的文字');return}blocks.value[i].text+=blocks.value[i+1].text;blocks.value.splice(i+1,1);ocrSaved.value=false}
function saveTranscript(){if(segments.value.some(s=>s.start<0||s.end<=s.start||s.end>2520)){ElMessage.warning('时间码须满足0≤开始<结束≤源时长2520秒');return}state.drafts['transcript-review']=segments.value;persist();ElMessage.success('已保存人工稿示意，机器初稿仍保留')}
function clip(){if(clipStart.value<0||clipEnd.value<=clipStart.value||clipEnd.value>2520){ElMessage.warning('请检查片段起止时间');return}if(!clipPurpose.value.trim()){ElMessage.warning('请填写片段用途');return}ElMessage.success('已记录演示选段申请，未转码或生成真实片段')}
function mark(e:MouseEvent){const rect=(e.currentTarget as HTMLElement).getBoundingClientRect();region.value={x:Math.round((e.clientX-rect.left)/rect.width*100),y:Math.round((e.clientY-rect.top)/rect.height*100)}}
async function ask(text=question.value){if(!text.trim())return;question.value=text;answerLoading.value=true;messages.value.push(text);await new Promise(r=>setTimeout(r,300));answerState.value=/无|未知|获奖/.test(text)?'证据不足':/冲突|不同/.test(text)?'来源冲突':'有依据';answer.value=answerState.value==='证据不足'?'当前可访问资料不足以确认。示例档案尚无已核验的对应成果记录，可请负责人补充凭证后再查询。':answerState.value==='来源冲突'?'两份演示记录的实际时长不同：场次记录为128分钟，录像文件为130分钟。可能包含谢幕片段，应由业务负责人核对，本页不自动覆盖档案。':'根据演示归档记录，《春江月》广州首演于2026年10月8日在城市剧院举行，实际主角为演员乙。[1] 对应归档录像为V2；当前工作版本已更新为V3，旧分享仍固定V2。[2]';answerLoading.value=false}
function exampleFile(e:Event){files.value.push(...Array.from((e.target as HTMLInputElement).files||[]).map(f=>f.name));ElMessage.info('仅登记本地文件名，未上传文件内容')}
async function submitContribution(){if(!consent.value){ElMessage.warning('请阅读并勾选授权声明');return}await ElMessageBox.alert('演示投稿已进入“待审核”。实际功能实现后还需经过隔离检查、权利核验和内部接收。','投稿流程演示');stateChoice.value='待审核'}
</script>
