  <template v-else><el-tag type="success">本人投稿空间 · 演示</el-tag><h2>广州首演影像征集</h2><p>截止：2026-10-12 18:00 · 剩余容量62GB / 100GB</p><el-alert v-if="stateChoice==='退回补充'" title="请补交摄影授权凭证，并填写作者及拍摄日期。" :closable="false"/><el-form label-position="top"><el-form-item label="作者 / 单位"><el-input model-value="摄影工作室"/></el-form-item><el-form-item label="拍摄日期"><el-date-picker model-value="2026-10-08" type="date"/></el-form-item><el-form-item label="内容说明"><el-input type="textarea" placeholder="说明场次、机位或拍摄内容"/></el-form-item></el-form><label class="file-pick">选择投稿文件<input type="file" multiple @change="exampleFile"/></label><ul class="submission-files"><li v-for="(name,i) in files" :key="i"><span>{{name}}</span><el-tag>{{stateChoice==='待审核'?'待审核':'待提交'}}</el-tag><el-button text @click="files.splice(i,1)">移除</el-button></li></ul><el-checkbox v-model="consent">我已阅读授权声明，并愿意提交凭证供院团核验。</el-checkbox><p class="muted">声明不自动代表权利完整；接收前可撤回，接收后需申请更正。此界面不上传文件内容。</p><el-button type="primary" @click="submitContribution">提交演示投稿</el-button></template>
 </div>
